ign/core/validate/source/projects-sdd-src-validate-rules-r3e_impl_mode_misuse-rs.md#source\nimpl Rule for ImplModeMisuseRule {\n    fn id(&self) -> RuleId {\n        RuleId::ImplModeMisuse\n    }\n\n    fn check(&self, spec_path: &Path, content: &str, report: &mut RuleReport) {\n        for block in extract_yaml_blocks(content) {\n            let Ok(yaml) = serde_yaml::from_str::<Value>(&block.body) else {\n                continue;\n            };\n            let changes = yaml\n                .get(\"changes\")\n                .and_then(|v| v.as_sequence())\n                .or_else(|| yaml.as_sequence());\n            let Some(changes) = changes else { continue };\n            for (idx, entry) in changes.iter().enumerate() {\n                let Some(map) = entry.as_mapping() else {\n                    continue;\n                };\n                let path_hint = map\n                    .get(Value::String(\"path\".into()))\n                    .and_then(|v| v.as_str())\n                    .map(|s| format!(\"changes[{}] ({})\", idx, s))\n                    .unwrap_or_else(|| format!(\"changes[{}]\", idx));\n                let Some(val) = map\n                    .get(Value::String(\"impl_mode\".into()))\n                    .and_then(|v| v.as_str())\n                else {\n                    report.push(\n                        Finding::error(\n                            RuleId::ImplModeMisuse,\n                            spec_path,\n                            \"missing impl_mode; every changes[] entry must declare codegen or hand-written\",\n                        )\n                        .with_path(path_hint),\n                    );\n                    continue;\n                };\n                if !ALLOWED.contains(&val) {\n                    report.push(\n                        Finding::error(\n                            RuleId::ImplModeMisuse,\n                            spec_path,\n                            format!(\"impl_mode `{}` is not in {{codegen, hand-written}}\", val),\n                        )\n                        .with_path(path_hint),\n                    );\n                }\n            }\n        }\n    }\n}\n\n#[cfg(test)]\nmod tests {\n    use super::*;\n    use std::path::PathBuf;\n\n    fn run(content: &str) -> RuleReport {\n        let mut r = RuleReport::new();\n        ImplModeMisuseRule {}.check(&PathBuf::from(\"test.md\"), content, &mut r);\n        r\n    }\n\n    #[test]\n    fn codegen_is_allowed() {\n        let spec = r#\"\n```yaml\nchanges:\n  - path: foo.rs\n    action: create\n    impl_mode: codegen\n```\n\"#;\n        assert!(run(spec).is_empty());\n    }\n\n    #[test]\n    fn hand_written_is_allowed() {\n        let spec = r#\"\n```yaml\nchanges:\n  - path: foo.rs\n    action: create\n    impl_mode: hand-written\n```\n\"#;\n        assert!(run(spec).is_empty());\n    }\n\n    #[test]\n    fn missing_impl_mode_is_flagged() {\n        let spec = r#\"\n```yaml\nchanges:\n  - path: foo.rs\n    action: create\n```\n\"#;\n        let r = run(spec);\n        assert_eq!(r.findings.len(), 1);\n        assert!(r.findings[0].message.contains(\"missing impl_mode\"));\n    }\n\n    #[test]\n    fn arbitrary_value_is_flagged() {\n        let spec = r#\"\n```yaml\nchanges:\n  - path: foo.rs\n    impl_mode: handwritten\n```\n\"#;\n        let r = run(spec);\n        assert_eq!(r.findings.len(), 1);\n        assert!(r.findings[0].message.contains(\"handwritten\"));\n    }\n\n    #[test]\n    fn typo_codegen_flagged() {\n        let spec = r#\"\n```yaml\nchanges:\n  - path: foo.rs\n    impl_mode: codegend\n```\n\"#;\n        assert_eq!(run(spec).findings.len(), 1);\n    }\n\n    #[test]\n    fn multiple_invalid_entries_all_flagged() {\n        let spec = r#\"\n```yaml\nchanges:\n  - path: a.rs\n    impl_mode: auto\n  - path: b.rs\n    impl_mode: manual\n```\n\"#;\n        let r = run(spec);\n        assert_eq!(r.findings.len(), 2);\n    }\n\n    #[test]\n    fn path_hint_includes_entry_index() {\n        let spec = r#\"\n```yaml\nchanges:\n  - path: a.rs\n    impl_mode: codegen\n  - path: b.rs\n    impl_mode: wrong\n```\n\"#;\n        let r = run(spec);\n        assert_eq!(r.findings.len(), 1);\n        assert!(r.findings[0]\n            .path\n            .as_deref()\n            .unwrap()\n            .contains(\"changes[1]\"));\n        assert!(r.findings[0].path.as_deref().unwrap().contains(\"b.rs\"));\n    }\n}\n/// ImplModeMisuseRule validation rule (unit struct).\n/// @spec apps/agentic-workflow/tech-design/core/validate/rules/r3e_impl_mode_misuse.md#schema\npub struct ImplModeMisuseRule {}\n````\n## Changes\n<!-- type: changes lang: yaml -->\n\n```yaml\nchanges:\n  - path: apps/agentic-workflow/src/validate/rules/r3e_impl_mode_misuse.rs\n    action: modify\n    section: source\n    impl_mode: codegen\n    description: |\n      Regenerate the remaining validation module source directly from the\n      source section. Existing schema CODEGEN blocks, when present, remain\n      owned by their semantic specs.\n```\n"
